root = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser(description='Rebuild the Qadam Russian guide (requires reportlab and DejaVu Sans fonts).')
parser.add_argument('--font-dir', type=Path, required=True, help='Directory containing DejaVuSans.ttf and DejaVuSans-Bold.ttf')
parser.add_argument('--output-dir', type=Path, default=root / 'output' / 'pdf', help='Generated PDF and Markdown destination')
args = parser.parse_args()
fonts = args.font_dir.expanduser().resolve()
output = args.output_dir.expanduser().resolve()
output.mkdir(parents=True, exist_ok=True)
for name in ('DejaVuSans.ttf', 'DejaVuSans-Bold.ttf'):
    if not (fonts / name).is_file():
        parser.error(f'Missing font: {fonts / name}')
pdfmetrics.registerFont(TTFont('DV',str(fonts/'DejaVuSans.ttf')))
pdfmetrics.registerFont(TTFont('DVB',str(fonts/'DejaVuSans-Bold.ttf')))
pdfmetrics.registerFontFamily('DV',normal='DV',bold='DVB')
styles={
 'title':ParagraphStyle('title',fontName='DVB',fontSize=23,leading=29,textColor=HexColor('#194f3e'),spaceAfter=16),
 'sub':ParagraphStyle('sub',fontName='DVB',fontSize=12.5,leading=17,textColor=HexColor('#194f3e'),spaceBefore=11,spaceAfter=7),
 'body':ParagraphStyle('body',fontName='DV',fontSize=10.3,leading=15.2,textColor=HexColor('#263d34'),spaceAfter=8),
 'small':ParagraphStyle('small',fontName='DV',fontSize=8.5,leading=12,textColor=HexColor('#52685c'),spaceAfter=6),
 'cell':ParagraphStyle('cell',fontName='DV',fontSize=9,leading=12.5,textColor=HexColor('#263d34')),
}
story=[];md=[]
def clean(t):return t.replace('—','-').replace('–','-').replace('‑','-')
def para(t,style='body'):story.append(Paragraph(clean(t),styles[style]));md.append(t.replace('<b>','**').replace('</b>','**')+'\n')
def heading(t):para(t,'sub')
def table(headers,rows,widths):
 data=[[Paragraph('<b>'+escape(c)+'</b>',styles['cell']) for c in headers]]+[[Paragraph(clean(escape(str(c))),styles['cell']) for c in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#e9f0e3')),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('LINEBELOW',(0,0),(-1,-1),.4,HexColor('#dce5dd'))]));story.append(t);story.append(Spacer(1,10));md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n')
def page(n,title,desc):
 if n>1:story.append(PageBreak())
 md.append('\n# '+str(n)+'. '+title+'\n');para(f'QADAM / РУКОВОДСТВО / {n:02d}','small');para(title,'title');para(desc)
page(1,'Что делает Qadam','Инструкция по приложению и план продвижения магазина и самого Qadam. Подготовлено 17 октября 2026 года для версии продукта 0.5. Планы и учебные примеры не являются обещанием роста продаж.')
para('<b>Qadam - помощник владельца магазина.</b> Он превращает историю продаж и остатки в обзор бизнеса, прогноз продаж и рекомендуемый план закупки. Затем помогает подготовить заказ поставщику и отслеживать счёт, оплату и получение.')
para('Основа: README 0.5 и код проекта. Внешние источники указаны на странице 8. Планы продвижения - предложенные гипотезы.','small')
